#!/usr/bin/env python3
"""Build useful, indexable creator tools without a frontend dependency."""
from pathlib import Path
import html, json, os

ROOT = Path(__file__).resolve().parents[1]
SITE = os.environ.get('CUEPROMPT_SITE', 'https://cueprompt-studio.mauvejay6.chatgpt.site').rstrip('/')
PAGES = {
    'script-templates': ('Script Template Builder', 'Choose a speaking format, add your ideas, and build a script you can rehearse immediately.', '''<div class="template-promise"><span class="template-badge">INSTANT TEMPLATE</span><strong>No AI key. No upload. Just a strong first draft.</strong><p>Choose a proven speaking structure, add your words, then edit the result before you read.</p><ol><li><b>1</b> Pick a format</li><li><b>2</b> Add your key points</li><li><b>3</b> Make it yours</li></ol></div><label>Format<select id="scene"><option value="youtube">YouTube introduction</option><option value="pitch">Product pitch</option><option value="course">Online lesson</option><option value="meeting">Team update</option><option value="podcast">Podcast opening</option><option value="speech">Short speech</option><option value="live">Livestream welcome</option><option value="interview">Self introduction</option></select></label><label>Script language<select id="language"><option value="en">English</option><option value="zh">简体中文</option></select></label><label>Topic / product / your name<input id="topic" maxlength="200" placeholder="A simpler way to plan your week"></label><label>Who is this for?<input id="audience" maxlength="200" placeholder="Busy creators"></label><label>Key points <span class="field-note">one thought per line</span><textarea id="points" rows="4" placeholder="The problem you solve&#10;Your practical advice&#10;A concrete example"></textarea></label><label>Closing action <span class="field-note">optional</span><input id="action" maxlength="300" placeholder="Try this today and share what changed"></label><button id="generate" class="primary">Generate template draft <span>→</span></button><p class="hint">This uses an on-device template, not an AI model. Your inputs stay in this browser.</p>'''),
    'script-extractor': ('Transcript Cleaner', 'Turn a public webpage, pasted transcript, subtitle file, image, audio or video into an editable speaking script. Local-first, with optional user-configured transcription.', '''<label>Import text or subtitles<input id="transcript-file" type="file" accept=".txt,.md,.srt,.vtt"></label><p class="hint">TXT, Markdown, SRT and VTT · up to 5 MB. Paste a YouTube transcript, import captions, or use the options below for public webpages, images, audio and video.</p><label>Transcript<textarea id="transcript" rows="10" placeholder="Paste your transcript or subtitle contents here"></textarea></label><button id="clean" class="primary">Clean transcript</button>'''),
    'publishing-assistant': ('Publishing Checklist & Copy Builder', 'Prepare a title, description and tags from your script, then export an editable publishing package.', '''<label>Video title<input id="video-title" maxlength="200" placeholder="What viewers will learn"></label><label>Script<textarea id="publish-script" rows="8" placeholder="Paste your finished script"></textarea></label><label>Call to action<input id="publish-action" maxlength="300" placeholder="Subscribe for the next lesson"></label><label>Keywords (comma separated)<input id="keywords" maxlength="500" placeholder="content creation, speaking, tutorial"></label><button id="package" class="primary">Build publishing copy</button><p class="hint">Uses your own words; no AI request or upload. Review the copy before publishing. Timed subtitles require a transcript aligned to your recording.</p>''')
}
PAGES['video-converter'] = ('Local Video Compressor & Converter', 'Compress a recording, convert MP4 or WebM, and fit it to landscape or portrait. Your video stays on this device.', '''<label>Recording<input id="media-file" type="file" accept="video/*"></label><p class="hint">Up to 150 MB. Keep this tab open while processing. The first use loads a 31 MB local processing engine. Large files may exceed your device memory.</p><label>Platform preset<select id="media-preset"><option value="custom">Custom export</option><option value="youtube">YouTube video · 16:9</option><option value="shorts">YouTube Shorts · 9:16</option><option value="tiktok">TikTok · 9:16</option><option value="reels">Instagram Reels · 9:16</option></select></label><p id="media-preset-note" class="hint">Choose a preset to fill recommended local export settings. Check each platform’s current upload rules before publishing.</p><label>Output format<select id="media-format"><option value="mp4">MP4 (H.264)</option><option value="webm">WebM (VP9)</option></select></label><label>Canvas<select id="media-canvas"><option value="original">Original aspect ratio</option><option value="portrait">Portrait 9:16 · fit with padding</option><option value="landscape">Landscape 16:9 · fit with padding</option></select></label><label>Quality<select id="media-quality"><option value="28">Smaller file</option><option value="23">Balanced</option><option value="18">Higher quality</option></select></label><button id="convert" class="primary">Compress / convert locally</button><button id="media-cancel" hidden>Cancel</button><p id="media-status" role="status"></p><progress id="media-progress" max="100" value="0"></progress>''')

SEO_COPY = {
    'script-templates': '<section class="seo-copy"><h2>Start with a proven script structure</h2><p>Choose a YouTube intro, product pitch, lesson, meeting update, podcast opener, speech, livestream welcome or self-introduction. Add your topic, audience and key points, then edit the draft before you read it.</p><h2>A private first draft, ready for the teleprompter</h2><p>The template builder runs in your browser. It does not need an AI key and does not upload your ideas. Send the finished draft to CuePrompt Studio when you are ready to rehearse.</p></section>',
    'script-extractor': '<section class="seo-copy"><h2>Turn a public webpage, transcript or recording into a speaking script</h2><p>Paste a YouTube transcript, import TXT, Markdown, SRT or VTT subtitles, or read a public webpage that allows browser access. Remove timestamps and filler formatting, then shape the result into an editable script.</p><h2>Keep control of your source material</h2><p>Text cleanup and OCR happen in this browser. Audio and video transcription is optional: you choose the provider, file and API key, then receive precise SRT captions when that provider returns timestamps.</p></section>',
    'publishing-assistant': '<section class="seo-copy"><h2>Turn a finished script into a publishing package</h2><p>Build an editable title, description, tags and publishing checklist from the words you already wrote. Use it as a review step before posting to YouTube, social video or a course platform.</p><h2>Your voice stays yours</h2><p>This tool organizes your supplied script locally. It does not generate claims or publish on your behalf, so you remain in control of the final copy.</p></section>',
    'video-converter': '<section class="seo-copy"><h2>Compress video in your browser</h2><p>Convert a recorded MP4 or WebM video, reduce its size, and prepare a portrait or landscape export without uploading the recording to a server.</p><h2>Export for the platform you are using</h2><p>Choose MP4 or WebM, select a quality level, review the local export, then continue to the publishing assistant to prepare your release copy.</p></section>',
}

for slug, (title, description, form) in PAGES.items():
    if slug == 'script-extractor':
        title = 'Script Extractor Lite'
        description = 'Turn a public webpage, transcript, image, audio or video into an editable speaking script. Local-first with optional user-configured transcription and precise SRT captions.'
    form = form.replace('WebM (VP9)', 'WebM (VP8)')
    links = ''.join(f'<a href="/{s}/" {"aria-current=page" if s == slug else ""}>{html.escape(v[0])}</a>' for s, v in PAGES.items())
    url = f'{SITE}/{slug}/'
    schema = json.dumps({'@context': 'https://schema.org', '@type': 'WebApplication', 'name': title, 'url': url, 'description': description, 'applicationCategory': 'MultimediaApplication', 'operatingSystem': 'Web browser', 'isAccessibleForFree': True, 'offers': {'@type': 'Offer', 'price': '0', 'priceCurrency': 'USD'}}, separators=(',', ':'))
    page = f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} | CuePrompt</title><meta name="description" content="{description}"><link rel="canonical" href="{url}"><meta property="og:title" content="{title} | CuePrompt"><meta property="og:description" content="{description}"><meta property="og:type" content="website"><meta property="og:url" content="{url}"><meta name="twitter:card" content="summary"><script type="application/ld+json">{schema}</script><link rel="stylesheet" href="/creator-tools.css"><link rel="stylesheet" href="/template-experience.css"><link rel="stylesheet" href="/template-gallery.css"><script src="/creator-tools.js" defer></script></head><body data-tool="{slug}"><header><a class="brand" href="/">CuePrompt</a><a href="/#studio">Open studio ↗</a></header><main><p class="eyebrow">FROM IDEA TO CAMERA</p><h1>{title}</h1><p class="intro">{description}</p><nav aria-label="Creator tools">{links}</nav><div class="workspace"><section class="card">{form}</section><section class="card"><div class="draft-heading"><div><span class="draft-kicker">YOUR DRAFT</span><h2>Review, then choose your next step.</h2></div><span class="local-dot">LOCAL</span></div><label>Title<input id="result-title" value="My next video"></label><label>Draft<textarea id="result" rows="16" placeholder="Your draft will appear here. You can edit it before using it."></textarea></label><p id="status" role="status" aria-live="polite"></p><div class="actions"><button id="read" class="primary">Start reading <span>→</span></button><button id="use">Edit in studio</button><button id="download">Download TXT</button><button id="copy">Copy</button></div></section></div>{SEO_COPY[slug]}<footer>Private by design. Drafts stay in this browser. <a href="/">Back to CuePrompt</a></footer></main></body></html>'''
    folder = ROOT / 'dist' / slug
    page = page.replace('<script src="/creator-tools.js" defer></script>', '<script src="/workflow.js" defer></script><script src="/creator-tools.js" defer></script><script src="/creator-advanced.js" defer></script>')
    page = page.replace('Private by design. Drafts stay in this browser.', 'Drafts stay in this browser. Optional transcription sends your selected recording to your chosen service.')
    if slug == 'script-extractor':
        page = page.replace('This tool cleans existing text; it does not transcribe audio, video or links.', 'Clean existing transcripts, extract printed text from images locally, or connect a transcription service for recordings.')
    if slug == 'script-templates':
        gallery = '''<section class="template-gallery"><p>CHOOSE A STARTING POINT</p><h2>What are you making?</h2><div class="template-grid"><button type="button" data-template-scene="youtube">▶ <b>Short video hook</b><small>Open strong and invite the next step.</small></button><button type="button" data-template-scene="live">◉ <b>Livestream welcome</b><small>Set the theme and guide chat.</small></button><button type="button" data-template-scene="pitch">◇ <b>Product introduction</b><small>Problem, value and proof.</small></button><button type="button" data-template-scene="course">▤ <b>Lesson or course</b><small>Teach one clear outcome.</small></button><button type="button" data-template-scene="podcast">◌ <b>Podcast opener</b><small>Welcome listeners to the episode.</small></button><button type="button" data-template-scene="interview">◒ <b>Interview introduction</b><small>Tell your story with structure.</small></button><button type="button" data-template-scene="speech">✦ <b>Talk or presentation</b><small>Build a memorable message.</small></button><button type="button" data-template-scene="meeting">→ <b>Team update</b><small>Progress, blockers, next steps.</small></button></div></section>'''
        page = page.replace('</div><label>Format', '</div>' + gallery + '<label>Format', 1)
    if slug == 'video-converter':
        start = page.index('<section class="card"><div class="draft-heading">')
        end = page.index('</section>', start) + len('</section>')
        page = page[:start] + '<section class="card"><h2>Review your export</h2><video id="media-preview" controls playsinline style="width:100%"></video><p id="media-summary"></p><a id="media-download" hidden>Download converted video</a><p><a href="/publishing-assistant/">Next: prepare publishing copy →</a></p></section>' + page[end:]
        page = page.replace('<script src="/creator-tools.js" defer></script><script src="/creator-advanced.js" defer></script>', '<script src="/video-converter.js" defer></script>')
    folder.mkdir(parents=True, exist_ok=True)
    (folder / 'index.html').write_text(page, encoding='utf-8')
